async () => { /* F2 KO under 'final': a ko verdict recorded at once, Volkov's mark locked guilty, no outcome shown (reveal end), the first-punch toast with 'A wrong one loses the mission.', the brass key on the floor */ await new Promise(r => setTimeout(r, 800)); const st = window.deductionRuntime.getState().state; const G = window.gameState.globalVariables; const T = JSON.stringify(window.__toasts);
  return st.verdicts.ded_d_volkov && st.verdicts.ded_d_volkov.kind === 'ko' && G.deduction_verdict_ded_d_volkov === 'guilty' && G.deduction_outcome_ded_d_volkov === ''
    && st.marks.ded_d_volkov && st.marks.ded_d_volkov.mark === 'guilty' && T.includes('Knocking out a suspect counts as accusing them.') && T.includes('A wrong one loses the mission.') && !/Right call|Wrong call/.test(T);  }

async () => { /* F3 no retry panel (retry 0); the debrief shows straight away: Chen wrong_guilty, 'You already held what settled it' naming the ward charm, no-blame line 'rule misread'; Volkov's ko verdict judged right_guilty at the call */ await new Promise(r => setTimeout(r, 1000)); const mg = window.MinigameFramework.currentMinigame; const t = mg.container.textContent; const st = window.deductionRuntime.getState().state;
  return !/Try again once/.test(t) && mg.getTestState().board.view === 'debrief' && st.verdicts.ded_d_chen.outcome === 'wrong_guilty' && st.verdicts.ded_d_volkov.outcome === 'right_guilty' && st.verdicts.ded_d_volkov.kind === 'ko'
    && /You already held what settled it/.test(t) && /ward charm/i.test(t) && mg.getTestState().board.debrief.noBlame === 'rule_misread';  }

async () => { /* F4 Finish: mission_failed 'wrong_call'; d_case_solved skipped; d_case_closed completed; the loss credits: header MISSION FAILED, non-victory playlist, title THE RITUAL COMPLETED, Chen's wrong-name line; MISSION COMPLETE nowhere (check 2/3) */ await new Promise(r => setTimeout(r, 4000)); const om = window.objectivesManager; const G = window.gameState.globalVariables; const h = document.querySelector('.bv-title-block h1'); const tk = document.querySelector('.bv-ticker-inner'); const body = document.body.textContent;
  return G.mission_failed === 'wrong_call' && om.taskIndex.d_case_solved.status === 'skipped' && om.taskIndex.d_case_closed.status === 'completed'
    && !!h && /MISSION FAILED/.test(h.textContent) && /THE RITUAL COMPLETED/.test(body) && /Mei Chen was named, and she had done nothing/.test(body)
    && (window.MusicController && window.MusicController.currentPlaylist) !== 'victory'
    && !!tk && /CASE CLOSED/.test(tk.textContent) && !/MISSION COMPLETE/.test(body);  }
